import json,shutil,html,re,hashlib
R=Path(__file__).resolve().parents[1];S=R/'docs';D=S/'data';D.mkdir(exist_ok=True)
m=json.loads((R/'reports/modelos_avanzados_metrics.json').read_text(encoding='utf-8'));d=json.loads((R/'reports/dataset_summary.json').read_text(encoding='utf-8'));f=m['final_test'];a=d['audit']
for x,y in [('modelos_avanzados_metrics.json','model_metrics.json'),('dataset_summary.json','dataset_summary.json'),('learning_curves_summary.json','learning_curves_summary.json')]:shutil.copy2(R/'reports'/x,D/y)
for p in (R/'reports/figures').glob('*.png'):
 if p.stat().st_mtime >= (R/'reports/data_quality_audit.json').stat().st_mtime-10:shutil.copy2(p,S/'assets'/p.name)
repo='https://github.com/J-Palma/ML1_2026-2';base=repo+'/blob/main/TP_4/proyecto-rodilla/'
def fig(name,caption):return f'<figure class="figure-card"><a href="assets/{name}" target="_blank"><img loading="lazy" src="assets/{name}" alt="{html.escape(caption)}"></a><figcaption>{caption}</figcaption></figure>'
def section(id,k,title,body):return f'<section class="section" id="{id}"><p class="eyebrow">{k}</p><h2>{title}</h2><div class="section-copy technical-copy">{body}</div></section>'
parts=[]
parts.append(f'''<section class="hero" id="inicio"><div><p class="eyebrow">PROYECTO FINAL · INGENIERÍA ELECTRÓNICA</p><h1>Artrosis de rodilla con <span>Machine Learning</span></h1><p class="hero-lede">Cinco grados y una evaluación reconstruida después de auditar duplicados.</p><div class="hero-actions"><a class="button primary" href="#demo">Explorar demo</a><a class="button secondary" href="{repo}">Código en GitHub ↗</a></div><p class="hero-context">Facultad de Ingeniería · Universidad Nacional de Asunción<br>Machine Learning 1 (23433) · Semestre 2026<br><strong>Jorge Javier Palma Martínez</strong><br><a href="mailto:jpalma@fiuna.edu.py">jpalma@fiuna.edu.py</a> · <a href="https://github.com/J-Palma">GitHub: J-Palma</a></p></div><div class="hero-visual"><div class="hero-center"><strong>{f['F1 Macro']:.3f}</strong><small>F1 macro · test reservado</small><strong>{m['feature_count']} variables</strong><small>seleccionadas de 288</small></div></div></section><section class="notice"><p><strong>Prototipo académico.</strong> No usar para diagnóstico ni decisiones clínicas. Versión: {m['protocol']}.</p></section>''')
parts.append(section('proyecto','01 · PROBLEMA','Clasificar cinco grados de severidad','''<p>La entrada es una radiografía y la etiqueta es Normal, Dudosa, Leve, Moderada o Severa (0–4). Son categorías ordenadas; los clasificadores entrenan como multiclase nominal.</p><h3>Justificación</h3><p>Se estudia si combinaciones aprendidas de intensidad, bordes y textura distinguen grados en imágenes de diferente contraste y formato. El experimento compara métodos; no demuestra superioridad frente a especialistas.</p><h3>Objetivo general</h3><p>Desarrollar un pipeline reproducible de clasificación de artrosis.</p><h3>Objetivos específicos</h3><ol><li>Auditar calidad, duplicados y etiquetas.</li><li>Extraer descriptores conservando la geometría.</li><li>Comparar selección ANOVA, PCA y modelos clásicos con validación.</li><li>Evaluar errores y presentar una demo, API y dashboard.</li></ol>'''))
counts=''.join(f'<tr><td>{x["name"]}</td><td>{x["count"]}</td></tr>' for x in d['classes'])
body=f'''<p>Fuente: <a href="https://www.kaggle.com/datasets/hafiznouman786/annotated-dataset-for-knee-arthritis-detection">Annotated Dataset for Knee Arthritis Detection, Kaggle</a>. De {d['raw_images']} originales se excluyeron {a['excluded_conflicting_images']} imágenes de {a['conflicting_label_groups']} grupos con etiquetas contradictorias y {a['removed_duplicate_copies']} copias exactas. Se conservó una imagen por hash de píxeles.</p><p><strong>Particiones:</strong> {d['splits']['train']} train, {d['splits']['validation']} validación y {d['splits']['test']} test. No comparten hashes idénticos. Se mantienen originales e inventario de inclusión. La copia limpia está en data/clean/Training y las exclusiones en data/excluded_images.csv.</p><p><strong>Corrección del protocolo:</strong> las cifras anteriores sobre 1.650 imágenes se reemplazaron: había 30 grupos duplicados entre particiones. Sin IDs de pacientes, todavía pueden existir recortes relacionados o duplicados aproximados.</p><div class="figure-grid">{fig('distribucion_clases.png','EDA 1. Distribución por grado después de depurar; persiste el desbalance.')}{fig('eda_resoluciones.png','EDA 2. Se mantienen ambas resoluciones; no son un criterio de exclusión.')}</div>{fig('eda_resolucion_por_grado.png','EDA 3. El formato sigue asociado al grado y puede introducir atajos visuales.')}<div class="table-wrap"><table><thead><tr><th>Grado</th><th>Imágenes únicas</th></tr></thead><tbody>{counts}</tbody></table></div><p><strong>Faltantes:</strong> extracción detenida ante imágenes ilegibles; no se imputan píxeles. <strong>Atípicos:</strong> no se eliminan por severidad o resolución; sin auditoría clínica. <strong>Codificación:</strong> etiquetas 0–4 y descriptores numéricos sin OneHotEncoder. <strong>Escalado:</strong> StandardScaler para modelos lineales, SVM, PCA y SVD; árboles sin ese escalado.</p>'''
parts.append(section('datos','02 · AUDITORÍA Y EDA',f"{d['total_images']} imágenes únicas elegibles",body))
body=f'''<p>Escala de grises, separación por la mitad de imágenes de al menos 500 píxeles de ancho, ajuste proporcional a 256 de ancho × 144 de alto y CLAHE (clip limit 1,5). La regla de anchura es específica del dataset; no detecta anatomía. En estudios bilaterales se promedian descriptores: la predicción corresponde al estudio, no a cada rodilla.</p>{fig('acondicionamiento_radiografias.png','Entrada rectangular real: proporción conservada, poco relleno añadido y CLAHE.')}<h3>Características y selección</h3><p>288 descriptores: 5 de intensidad, 3 de gradientes/Laplaciano, 16 bins de histograma, 8 estadísticas espaciales y 256 HOG. Se comparó ANOVA (40, 80 y 160 variables), PCA (32, 64 y 128 componentes) y subespacios SVD sobre píxeles 64 × 36. La máscara excluye el relleno añadido de estadísticas, histogramas y gradientes; no elimina el fondo original. HOG conserva proporciones sobre 160 × 96 píxeles.</p><p><strong>Elegido:</strong> {m['selected_model']} con F1 macro de validación {f['validation_f1']:.4f}. El modelo final conserva {m['feature_count']} variables. PCA se evaluó, pero no se eligió.</p>{fig('feature_engineering_validation.png','Comparación de representación exclusivamente en validación.')}<h3>Evaluación y fuga de datos</h3><p>70/15/15 estratificado por clase y resolución, semilla 42. Selección de parámetros, representación y familia por F1 macro de validación. Luego reentrenamiento con train + validation; decisión guardada antes de calcular resultados de test.</p><p>Curvas con StratifiedKFold de 3 folds dentro de train. Cada fold reajusta selector y escalador. Son diagnósticas posteriores a la búsqueda, no validación anidada ni externa. Se reutiliza el test ya evaluado en v2: los resultados son descriptivos y no una nueva confirmación independiente. La auditoría elimina duplicados exactos; sin IDs no garantiza separación por paciente.</p><h3>Modelos y barrido</h3><p>Logística L2 (C=0,001 a 10), SVM RBF (C=1, 10, 50), Random Forest (100–300 árboles; hoja 1 o 2), XGBoost (100–300 rondas, profundidad 4), SVD (k=5, 10, 20, 30, 50) y Dummy mayoritaria como referencia. XGBoost crea cinco árboles por ronda: 300 rondas son 1.500 árboles.</p><h3>Métricas</h3><p>F1 macro pondera por igual cada grado; balanced accuracy promedia recalls. Accuracy mide aciertos totales. Precisión/recall por clase, ROC One-vs-Rest y kappa cuadrático complementan el análisis ordinal.</p>'''
parts.append(section('metodo','03 · METODOLOGÍA','De la radiografía al modelo final',body))
rows=''.join(f'<tr><td>{x["Modelo"]}</td><td>{x["validation_f1"]:.4f}</td><td>{x["Accuracy (%)"]:.2f}%</td><td>{x["Balanced Acc (%)"]:.2f}%</td><td>{x["F1 Macro"]:.4f}</td></tr>' for x in sorted(m['comparison_table'],key=lambda x:x['F1 Macro'],reverse=True))
perclass=''.join(f'<tr><td>{k}</td><td>{v["precision"]:.3f}</td><td>{v["recall"]:.3f}</td><td>{v["f1-score"]:.3f}</td><td>{int(v["support"])}</td></tr>' for k,v in m['classification_report'].items() if k in ['Normal','Dudosa','Leve','Moderada','Severa'])
curves=json.loads((R/'reports/learning_curves_summary.json').read_text(encoding='utf-8'))
discussion=''.join(f'<p><strong>{x["model"]}</strong>: F1 train {x["train_f1"]:.3f} frente a CV {x["cv_f1"]:.3f}. La brecha es compatible con sobreajuste; la curva usa menos ejemplos de ajuste que el modelo final reentrenado.</p>' for x in curves)
body=f'''<div class="winner-card"><div><span class="winner-label">ELEGIDO POR VALIDACIÓN</span><h3>{m['selected_model']}</h3><p>Accuracy test {f['Accuracy (%)']:.2f}% · Balanced acc. {f['Balanced Acc (%)']:.2f}%</p></div><div class="winner-score"><span>{f['F1 Macro']:.3f}</span><small>F1 macro test</small></div></div><p>Test reservado: {m['test_size']} imágenes. Se retiene por familia su mejor configuración de validación. Kappa cuadrático final: {m['quadratic_kappa']:.4f}.</p><div class="metric-controls"><label for="metric-select">Comparar por</label><select id="metric-select"><option value="F1 Macro">F1 macro</option><option value="Accuracy (%)">Accuracy</option><option value="Balanced Acc (%)">Balanced accuracy</option></select></div><div id="model-chart" class="model-chart"></div><div class="table-wrap"><table><thead><tr><th>Modelo</th><th>F1 val.</th><th>Accuracy test</th><th>Balanced acc.</th><th>F1 test</th></tr></thead><tbody>{rows}</tbody></table></div><div class="figure-grid">{fig('final_confusion_normalizada.png','Matriz normalizada por grado real del modelo final.')}{fig('modelos_avanzados_roc_curves.png','ROC del modelo final: cada grado frente al resto.')}</div><div class="table-wrap"><table><thead><tr><th>Grado</th><th>Precisión</th><th>Recall</th><th>F1</th><th>N test</th></tr></thead><tbody>{perclass}</tbody></table></div>{fig('modelos_avanzados_learning_curves.png','Entrenamiento frente a CV; la brecha muestra riesgo de sobreajuste.')}<h3>Discusión</h3>{discussion}<p>La elección corresponde al mayor F1 de validación entre los candidatos definidos. La tabla de test es descriptiva y no redefine esa elección. El tamaño de la cohorte y las diferencias entre validación y test impiden generalizar ese orden a otros datasets.</p>{fig('modelos_avanzados_feature_importance.png','Importancia del XGBoost comparado, no explicación causal del modelo final.')}'''
parts.append(section('resultados','04 · RESULTADOS','Decisión congelada antes del test',body))
parts.append(section('demo','05 · DEMO INTERACTIVA','Explorar predicciones del test','''<p>Elegí una muestra para ver su etiqueta, decisión y puntuaciones. Son resultados precalculados con el pipeline publicado, no inferencia sobre nuevas imágenes en el navegador.</p><label for="sample-select">Muestra de prueba</label><select id="sample-select"></select><div class="demo-grid"><figure class="figure-card"><img id="demo-image" alt="Radiografía de la muestra elegida"><figcaption id="demo-label"></figcaption></figure><div><h3 id="demo-prediction"></h3><div id="demo-probabilities" class="model-chart"></div><p class="small-note">El clasificador decide con su regla de predicción. El orden de probabilidades puede diferir; no son certezas clínicas.</p></div></div><h3>Probar imágenes nuevas</h3><p>El repositorio incluye un dashboard Streamlit con inferencia local y modo API HTTP. FastAPI expone POST /predict. El README describe cómo ejecutar ambos servicios; no es necesario desplegar Python para navegar por este portal.</p>'''))
parts.append(section('limites','06 · CONCLUSIONES','Alcance y próximos pasos',f'''<p class="conclusion">Tras auditar duplicados y etiquetas, y reentrenar con la representación rectangular, validación eligió {m['selected_model']}. F1 macro de test {f['F1 Macro']:.4f}. El test ya se había examinado en v2; la revisión no aporta una confirmación independiente. Los resultados sobre la partición inicial con duplicados quedan reemplazados.</p><h3>Limitaciones</h3><p>Sin IDs de paciente, cohorte externa ni revisión especializada. Pueden existir recortes relacionados; formato y presencia de dos rodillas pueden sesgar el modelo. El promedio bilateral pierde lateralidad. Pérdida nominal para una etiqueta ordinal; puntuaciones sin calibración clínica.</p><h3>Trabajo futuro</h3><ul><li>Separación por paciente y auditoría de similitud aproximada.</li><li>Validación externa y revisión de etiquetas con especialistas.</li><li>Regularización, clasificación ordinal y calibración con datos separados.</li><li>Comparación con extractores preentrenados bajo protocolo congelado.</li></ul>'''))
parts.append(section('entregables','07 · ENTREGA','Código y documentos reproducibles',f'''<div class="hero-actions"><a class="button primary" href="{base}reports/informe_final.pdf">Informe PDF</a><a class="button secondary" href="{base}presentation/slides.pdf">Presentación PDF</a><a class="button secondary" href="{repo}/tree/main/TP_4/proyecto-rodilla/notebooks">Seis notebooks</a><a class="button secondary" href="{base}README.md">Ejecución y pruebas</a></div><p>Inventario y particiones con rutas relativas y hashes. El dataset completo se descarga desde Kaggle. La API y su Dockerfile acompañan el dashboard; el portal consume archivos estáticos.</p>'''))
nav=''.join(f'<a href="#{x}">{y}</a>' for x,y in [('proyecto','Proyecto'),('datos','Datos'),('metodo','Método'),('resultados','Resultados'),('demo','Demo'),('entregables','Entrega')])
(S/'index.html').write_text(f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Artrosis de rodilla · Proyecto final ML1 FIUNA</title><meta name="description" content="Clasificación de grados de artrosis con evaluación depurada, selección de variables y demo académica."><link rel="stylesheet" href="assets/site.css"><script defer src="assets/site.js"></script></head><body><header class="topbar"><a class="brand" href="#inicio">ML1 · FIUNA 2026</a><button class="menu-toggle" aria-label="Abrir navegación" aria-expanded="false">☰</button><nav class="nav-links" aria-label="Navegación principal">{nav}</nav></header><main>{''.join(parts)}</main><footer class="footer"><div><strong>Jorge Javier Palma Martínez</strong><p>Machine Learning 1 · FIUNA · 2026</p></div><div class="footer-links"><a href="{repo}">Repositorio</a><a href="https://github.com/carlobeni/Machine-Learning">Referencia de la cátedra</a><a href="https://www.youtube.com/watch?v=isgBodVA2C4">Video de referencia</a></div></footer></body></html>''',encoding='utf-8')
js='''let metrics;function render(key){const max=key==='F1 Macro'?1:100;document.querySelector('#model-chart').innerHTML=[...metrics.comparison_table].sort((a,b)=>b[key]-a[key]).map(x=>`<div class="model-bar-row"><span>${x.Modelo}</span><div class="model-track"><span class="model-fill" style="width:${100*x[key]/max}%"></span></div><strong>${x[key].toFixed(key==='F1 Macro'?3:1)}</strong></div>`).join('');}Promise.all([fetch('data/model_metrics.json').then(r=>r.json()),fetch('data/demo_predictions.json').then(r=>r.json())]).then(([m,samples])=>{metrics=m;render('F1 Macro');document.querySelector('#metric-select').addEventListener('change',e=>render(e.target.value));const select=document.querySelector('#sample-select');select.innerHTML=samples.map((s,i)=>`<option value="${i}">${s.actual_name} · ejemplo ${i%2+1}</option>`).join('');const show=()=>{const s=samples[Number(select.value)];document.querySelector('#demo-image').src=s.image;document.querySelector('#demo-label').textContent='Etiqueta del dataset: '+s.actual_name;document.querySelector('#demo-prediction').textContent='Predicción: '+s.class_name;document.querySelector('#demo-probabilities').innerHTML=Object.entries(s.probabilities).map(([k,v])=>`<div class="model-bar-row"><span>${k}</span><div class="model-track"><span class="model-fill" style="width:${v*100}%"></span></div><strong>${(v*100).toFixed(1)}%</strong></div>`).join('');};select.addEventListener('change',show);show();}).catch(e=>{document.querySelector('#model-chart').textContent='No se pudieron cargar los resultados. Recargá la página.';console.error(e);});const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=document.querySelector('.nav-links').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('.nav-links').classList.remove('open');menu.setAttribute('aria-expanded','false');}));'''
# Version resources together so returning visitors do not combine old JS/data with new HTML.
version=m['protocol']
js=js.replace("fetch('data/model_metrics.json')", "fetch('data/model_metrics.json?v="+version+"')").replace("fetch('data/demo_predictions.json')", "fetch('data/demo_predictions.json?v="+version+"')")
js=js.replace('src=s.image;', "src=s.image+'?v="+version+"';")
(S/'assets/site.js').write_text(js,encoding='utf-8')
page=S/'index.html'
markup=page.read_text(encoding='utf-8')
markup=re.sub(r'((?:src|href)="assets/[^"?]+)(")',lambda match:match[1]+'?v='+version+match[2],markup)
page.write_text(markup,encoding='utf-8')
p=S/'assets/site.css';s=p.read_text(encoding='utf-8');extra='\n.demo-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:24px}.demo-grid img{min-height:160px}select{max-width:100%;padding:10px;border:1px solid #d9e2ec;border-radius:7px}.hero-center{width:200px;height:200px}.hero-center strong:first-child{font-size:38px}section[id]{scroll-margin-top:90px}@media(max-width:800px){.demo-grid{grid-template-columns:1fr}.nav-links{gap:14px}}\n';p.write_text(s+extra if '.demo-grid{' not in s else s,encoding='utf-8')
# A style edit must reach returning visitors without changing the ML protocol.
style_version=hashlib.sha256(p.read_bytes()).hexdigest()[:12]
page.write_text(page.read_text(encoding='utf-8').replace(
    'assets/site.css?v='+version,'assets/site.css?v='+style_version),encoding='utf-8')
print('Sitio construido:',m['protocol'])

